CAchievement* CAchievements::getAchievement(EACHIEVEMENTS achievement)
{
    std::map<EACHIEVEMENTS, CAchievement*>::iterator found = m_achievementsById.find(achievement);
    if (found == m_achievementsById.end())
        return NULL;
    return found->second;
}

void CAchievements::synchAchievementsComplete()
{
    m_bUnknown10 = true;
}

void CAchievements::update(float)
{
    m_completedAchievements.clear();
}

void CAchievements::cheat()
{
    for (unsigned int i = 0; i < m_achievements.size(); ++i)
        m_achievements[i]->cheat();
}

CAchievements::~CAchievements()
{
    m_achievements.deleteAll();
    m_gAchievementsObject = NULL;
}

CAchievement* CAchievements::getAchievement(std::basic_string<char, std::char_traits<char>, std::allocator<char> > name)
{
    for (unsigned int i = 0; i < m_achievements.size(); ++i)
    {
        if (std::string(m_achievements[i]->m_strName) == name)
            return m_achievements[i];
    }
    return NULL;
}

void CAchievements::setAchievementComplete(CAchievement* achievement)
{
    m_completedAchievements.add(achievement);
}

void CDropdownMenu::broadcastEvent(EMENU_TYPE type, EMENU_EVENT event)
{
    for (unsigned int i = 0; i < m_pendingMenuListeners.size(); ++i)
        m_menuListeners.remove(m_pendingMenuListeners[i]);
    m_pendingMenuListeners.clear();
    for (unsigned int i = 0; i < m_menuListeners.size(); ++i)
        m_menuListeners[i]->menuEventOccured(this, type, event);
}

void CDropdownMenu::addMenuListener(iMenuListener* listener)
{
    if (m_menuListeners.find(listener) == -1)
    {
        m_pendingMenuListeners.remove(listener);
        m_menuListeners.add(listener);
    }
}

CDropdownMenu::~CDropdownMenu()
{
    if (m_pGenericModel)
    {
        delete m_pGenericModel;
        m_pGenericModel = NULL;
    }
    if (m_pSoundBank)
    {
        delete m_pSoundBank;
        m_pSoundBank = NULL;
    }
    m_menuListeners.clear();
    m_pendingMenuListeners.clear();
}

void CDropdownMenu::removeMenuListener(iMenuListener* listener)
{
    m_pendingMenuListeners.add(listener);
}

CSpawnClassParser* CSpawnClassParser::getSingleton()
{
    return m_gSpawnClassParser;
}

void CSpawnClassParser::clear()
{
    for (std::map<std::wstring, CSpawnClassData*>::iterator it = m_spawnClassData.begin();
         it != m_spawnClassData.end(); ++it)
    {
        if (it->second)
        {
            delete it->second;
            it->second = NULL;
        }
    }
    m_spawnClassData.clear();
    for (std::map<std::wstring, CSpawnClass*>::iterator it = m_spawnClasses.begin();
         it != m_spawnClasses.end();)
    {
        CSpawnClass* spawnClass = it->second;
        ++it;
        delete spawnClass;
    }
    m_spawnClasses.clear();
}

CSpawnClassParser::~CSpawnClassParser()
{
    clear();
    m_gSpawnClassParser = NULL;
}

CSpawnClassData* CSpawnClassParser::getSpawnClassDataByName(const std::wstring& name)
{
    std::map<std::wstring, CSpawnClassData*>::iterator found = m_spawnClassData.find(STRINGS::StringUpper(name));
    if (found == m_spawnClassData.end())
        return NULL;
    return found->second;
}

CSpawnClass* CSpawnClassParser::getSpawnClass(const std::wstring& name)
{
    std::map<std::wstring, CSpawnClass*>::iterator found = m_spawnClasses.find(STRINGS::StringUpper(name));
    if (found == m_spawnClasses.end())
        return NULL;
    return found->second;
}

int CInventory::getPaneIndex(EINVENTORY_PANES pane)
{
    for (int i = m_paneStarts.size() - 1; i >= 0; --i)
    {
        if (m_panes[i] == pane)
            return i;
    }
    return 0;
}

int CInventory::getPaneSize(EINVENTORY_PANES pane)
{
    unsigned int index = getPaneIndex(pane);
    if (index == m_paneStarts.size() - 1)
        return m_iUnknown28 - m_paneStarts[index];
    return m_paneStarts[index + 1] - m_paneStarts[index];
}

bool CInventory::slotIsInPane(unsigned int pane, int slot)
{
    int start = m_paneStarts[pane];
    int end = m_iUnknown28;
    if (pane < m_paneStarts.size() - 1)
        end = m_paneStarts[pane + 1];
    return slot >= start && slot < end;
}

int CInventory::getItemPane(unsigned int slot)
{
    for (unsigned int i = 0; i < m_paneStarts.size(); ++i)
    {
        if (slot >= m_paneStarts[i] &&
            (i == m_paneStarts.size() - 1 || slot < m_paneStarts[i + 1]))
            return i;
    }
    return 0;
}

void CInventory::addSection(EINVENTORY_PANES pane, unsigned int size)
{
    m_panes.push_back(pane);
    m_paneStarts.push_back(m_iUnknown28);
    m_iUnknown28 += size;
}

bool CConsole::getVisible()
{
    return m_window ? m_window->isVisible(false) : false;
}

void CConsole::setVisible(bool visible)
{
    if (m_window)
    {
        if (visible)
        {
            m_window->setVisible(true);
            m_window->activate();
            m_window->moveToFront();
            m_inputWindow->setText(CEGUI::String());
        }
        else
            m_window->setVisible(false);
    }
}

bool CConsole::handleClose(const CEGUI::EventArgs&)
{
    setVisible(false);
    return true;
}

std::wstring CConsole::getHistoryText()
{
    std::wstring text = EMPTY_WSTRING;
    if (m_historyWindow)
        text = STRINGS::StringConvertToWide(m_historyWindow->getText().c_str(), 5000);
    return text;
}

CConsole::~CConsole()
{
    CEGUI::WindowManager::getSingleton().destroyWindow(m_window);
    m_window = NULL;
    m_inputWindow = NULL;
}
